<script setup lang="ts">
import { resourceLabels,resourceIcons,money,portalDate,type ResourceKind,type PortalResource } from '~/types/portal'
type View='home'|'project'|ResourceKind
const route=useRoute(), router=useRouter()
const view=computed<View>(()=>['home','project',...Object.keys(resourceLabels)].includes(String(route.query.tab))?String(route.query.tab) as View:'home')
const navigate=(tab:View)=>router.replace({query:{...route.query,tab}})
const user=ref({name:'',email:'',role:''}),organization=ref(''),ready=ref(false),loading=ref(false),error=ref('')
const project=ref({id:'',name:'',description:'',status:'',progress:0,dueDate:'',currentPhase:'Cadrage'})
const projects=ref<{id:string;name:string}[]>([]), resources=ref<PortalResource[]>([]), activity=ref<{id:string;message:string;createdAt:string}[]>([])
const phaseNames=['Cadrage','Design','Développement','Mise en ligne']
const phaseIndex=computed(()=>Math.max(0,phaseNames.indexOf(project.value.currentPhase)))
const payments=computed(()=>resources.value.filter(r=>r.kind==='payment'&&r.status==='due'))
const reviews=computed(()=>resources.value.filter(r=>r.kind==='mockup'&&r.status==='pending'))
const overviewTab=ref<'resources'|'activity'>('resources')
const resourceSearch=ref(''), resourceFilter=ref('all'), resourceSort=ref('recent')
const statusLabels:Record<string,string>={available:'Disponible',due:'À régler',paid:'Réglé',cancelled:'Annulé',pending:'À valider',approved:'Validée',changes:'À modifier'}
const visibleResources=computed(()=>resources.value.filter(r=>(resourceFilter.value==='all'||r.kind===resourceFilter.value)&&(r.title+' '+r.description).toLowerCase().includes(resourceSearch.value.toLowerCase())).slice().sort((a,b)=>resourceSort.value==='name'?a.title.localeCompare(b.title,'fr'):b.createdAt.localeCompare(a.createdAt)))
const navigation=[{id:'home' as View,label:'Vue d’ensemble',icon:'i-tabler-home'},{id:'project' as View,label:'Suivi du projet',icon:'i-tabler-layout-board'},...Object.entries(resourceLabels).map(([id,label])=>({id:id as View,label,icon:resourceIcons[id as ResourceKind]}))]
const refresh=async()=>{const data=await $fetch<{resources:PortalResource[];activity:typeof activity.value}>('/api/portal/resources',{query:{projectId:project.value.id}});resources.value=data.resources;activity.value=data.activity}
const loadProject=async(id?:string)=>{
 loading.value=true;error.value=''
 try{const data=await $fetch<{project:typeof project.value;projects:typeof projects.value}>('/api/portal/client/project',{query:id?{projectId:id}:{}});project.value=data.project;projects.value=data.projects;await refresh()}
 catch(e:any){error.value=e?.data?.statusMessage || 'Impossible de charger votre espace.'}
 finally{loading.value=false}
}
const signOut=async()=>{await $fetch('/api/portal/auth/logout',{method:'POST'});await navigateTo('/portal/login')}
useHead({title:computed(()=>`${organization.value || 'Votre projet'} · MC Studio`),meta:[{name:'robots',content:'noindex,nofollow'}]})
onMounted(async()=>{
 try{const me=await $fetch<{user:typeof user.value|null;organization?:{name:string}}>('/api/portal/auth/me');if(!me.user){await navigateTo('/portal/login');return}if(me.user.role==='admin'){await navigateTo('/portal/admin');return}user.value=me.user;organization.value=me.organization?.name || 'Votre espace';await loadProject()}
 catch{error.value='Impossible de charger votre compte. Réessayez.'}finally{ready.value=true}
})
</script>
<template>
 <main class="portal">
  <aside class="sidebar"><div class="brand"><PortalBrand/><span>Espace de travail</span></div><div class="identity"><span>{{organization.slice(0,1) || 'M'}}</span><div><strong>{{organization || 'MC Studio'}}</strong><small>ESPACE CLIENT</small></div><UIcon name="i-tabler-lock"/></div><p class="nav-label">ESPACE CLIENT</p><nav aria-label="Espace client"><button v-for="item in navigation" :key="item.id" :class="{active:view===item.id}" @click="navigate(item.id)"><UIcon :name="item.icon"/>{{item.label}}<span v-if="item.id==='payment'&&payments.length" class="count">{{payments.length}}</span><span v-if="item.id!=='home' && item.id!=='project' && item.id!=='payment'" class="count">{{resources.filter(r=>r.kind===item.id).length}}</span></button></nav><div class="sidebar-bottom"><p class="nav-label">ASSISTANCE</p><a href="https://wa.me/33781724683" target="_blank" rel="noopener noreferrer">Contacter l’équipe<UIcon name="i-tabler-arrow-up-right"/></a><button @click="signOut"><UIcon name="i-tabler-logout"/>Se déconnecter</button></div></aside>
  <div class="main"><header><div class="header-title">{{navigation.find(n=>n.id===view)?.label}} <span class="header-status"><i/>{{project.status || 'Espace privé'}}</span></div><div class="portal-header-actions"><PortalThemeToggle /><div class="user"><i>{{user.name.slice(0,1)}}</i><span>{{user.name}}</span><button class="mobile-exit" aria-label="Se déconnecter" @click="signOut"><UIcon name="i-tabler-logout"/></button></div></div></header>
   <div class="content">
    <p v-if="!ready || loading" class="loading" role="status">Ouverture de votre espace…</p>
    <p v-if="error" class="error" role="alert">{{error}} <button @click="loadProject()">Réessayer</button></p>
    <template v-if="ready && project.id && !loading">
     <label v-if="projects.length>1" class="project-picker">Votre projet<select :value="project.id" @change="loadProject(($event.target as HTMLSelectElement).value)"><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label>
     <template v-if="view==='home'">
      <div class="workspace-heading"><div><h1>{{project.name}}</h1><p>{{organization}} <span>·</span> Votre espace partagé avec MC Studio</p></div><button class="main-action" @click="navigate(reviews.length?'mockup':'project')"><UIcon :name="reviews.length?'i-tabler-check':'i-tabler-arrow-up-right'"/>{{reviews.length?'Valider les maquettes':'Voir le projet'}}</button></div>
      <div class="project-strip"><div><span>Étape actuelle</span><strong><UIcon name="i-tabler-layout-board"/>{{project.currentPhase}}</strong></div><div><span>Avancement</span><strong><span class="mini-progress"><i :style="{width:project.progress+'%'}"/></span>{{project.progress}} %</strong></div><div><span>Livraison prévue</span><strong><UIcon name="i-tabler-calendar"/>{{portalDate(project.dueDate)}}</strong></div><button @click="navigate('payment')"><span>À régler</span><strong>{{money(payments.reduce((sum,p)=>sum+p.amount,0))}}<UIcon name="i-tabler-arrow-up-right"/></strong></button></div>
      <nav class="workspace-tabs" aria-label="Vue d’ensemble"><button :class="{selected:overviewTab==='resources'}" @click="overviewTab='resources'">Ressources <span>{{resources.length}}</span></button><button :class="{selected:overviewTab==='activity'}" @click="overviewTab='activity'">Activité <span>{{activity.length}}</span></button></nav>
      <template v-if="overviewTab==='resources'">
       <div class="table-toolbar"><label class="filter-pill"><span>Type</span><select v-model="resourceFilter" aria-label="Filtrer les ressources par type"><option value="all">Toutes les ressources</option><option v-for="(label,key) in resourceLabels" :key="key" :value="key">{{label}}</option></select></label><label class="filter-pill"><span>Trier par</span><select v-model="resourceSort" aria-label="Trier les ressources"><option value="recent">Plus récent</option><option value="name">Nom</option></select></label><label class="table-search"><UIcon name="i-tabler-search"/><input v-model="resourceSearch" placeholder="Rechercher…" aria-label="Rechercher dans le projet"></label></div>
       <div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>Nom de la ressource</th><th>Type</th><th>Statut</th><th>Date d’ajout</th><th class="action-col">Action</th></tr></thead><tbody><tr v-for="r in visibleResources" :key="r.id"><td><button class="resource-name" @click="navigate(r.kind)"><UIcon :name="resourceIcons[r.kind]"/><span>{{r.title}}<small v-if="r.fileName">{{(r.fileSize/1024/1024).toFixed(2)}} Mo</small></span></button></td><td><span class="type-tag">{{resourceLabels[r.kind]}}</span></td><td><span class="status-tag"><i :class="{filled:['approved','paid','available'].includes(r.status)}"/>{{statusLabels[r.status] || r.status}}</span></td><td class="date-cell">{{portalDate(r.createdAt)}}</td><td class="action-col"><button class="open-row" :aria-label="'Ouvrir '+r.title" @click="navigate(r.kind)"><UIcon name="i-tabler-arrow-up-right"/></button></td></tr><tr v-if="!visibleResources.length"><td colspan="5" class="empty-table">{{resourceSearch?'Aucune ressource ne correspond à votre recherche.':'Les ressources partagées par MC Studio apparaîtront ici.'}}</td></tr></tbody></table></div>
       <div class="table-summary"><span>{{visibleResources.length}} ressource{{visibleResources.length>1?'s':''}} affichée{{visibleResources.length>1?'s':''}}</span><span><UIcon name="i-tabler-lock"/> Accessible uniquement à votre équipe</span></div>
      </template>
      <section v-else class="updates"><div v-if="!activity.length" class="empty-updates">Aucune activité pour le moment.</div><article v-for="item in activity" :key="item.id"><span class="activity-dot"/><p>{{item.message}}</p><time>{{portalDate(item.createdAt)}}</time></article></section>
     </template>
     <template v-else-if="view==='project'"><div class="page-title"><h1>{{project.name}}</h1><p>{{project.description}}</p></div><section class="timeline"><article v-for="(phase,i) in phaseNames" :key="phase" :class="{current:i===phaseIndex,done:i<phaseIndex}"><span>{{i<phaseIndex?'✓':String(i+1).padStart(2,'0')}}</span><div><small>{{i<phaseIndex?'TERMINÉ':i===phaseIndex?'EN COURS':'À VENIR'}}</small><h2>{{phase}}</h2><p>{{['Nous définissons ensemble les objectifs, les contenus et le périmètre du projet.','Nous donnons forme à votre identité et préparons les maquettes à valider.','Nous construisons votre site ou application et intégrons vos contenus.','Nous préparons la livraison et vous accompagnons dans la prise en main.'][i]}}</p><button v-if="phase==='Design'" class="text-link" @click="navigate('mockup')">Consulter les maquettes →</button></div></article></section><section class="updates"><h2>Journal du projet</h2><p v-if="!activity.length">Les nouvelles étapes seront consignées ici.</p><article v-for="item in activity" :key="item.id"><span class="activity-dot"/><p>{{item.message}}</p><time>{{portalDate(item.createdAt)}}</time></article></section></template>
     <PortalResources v-else :key="project.id" :project-id="project.id" :kind="view as ResourceKind" @changed="refresh"/>
    </template>
   </div>
  </div>
 </main>
</template>
<style scoped>
