-bottom-color:var(--portal-line, #ddd)}.workspace-tabs button>span{background:var(--portal-raised, #252525);border:1px solid var(--portal-line, #343434);padding:0 5px;border-radius:4px;font-size:10px;color:var(--portal-muted, #aaa)}.table-toolbar{display:flex;align-items:center;gap:9px;padding:16px 24px;border-bottom:1px solid var(--portal-line, #2b2b2b)}.filter-pill{display:flex;align-items:center;border:1px solid var(--portal-line, #3b3b3b);border-radius:99px;background:var(--portal-surface, #202020);overflow:hidden;white-space:nowrap;font-size:11px}.filter-pill>span{color:var(--portal-muted, #777);padding:7px 10px;border-right:1px solid var(--portal-line, #373737)}.filter-pill select{padding:7px 9px;color:var(--portal-text, #ccc);border:0;background:transparent;outline-offset:-3px}.filter-pill option{background:var(--portal-raised, #222)}.table-search{display:flex;align-items:center;gap:8px;margin-left:auto;color:var(--portal-muted, #777)}.table-search input{width:145px;background:transparent;border:0;color:var(--portal-text, #ddd);outline-offset:3px;font-size:11px}.resource-table-wrap{width:100%;overflow-x:auto}.resource-table{width:100%;border-collapse:collapse;white-space:nowrap;text-align:left}.resource-table th{padding:12px 20px;font-size:10px;font-weight:400;color:var(--portal-muted, #777);border-bottom:1px solid var(--portal-line, #2b2b2b)}.resource-table th:first-child{padding-left:24px;width:40%}.resource-table td{height:59px;padding:9px 20px;border-bottom:1px solid var(--portal-line, #292929);font-size:11px}.resource-table td:first-child{padding-left:24px}.resource-table tbody tr:hover{background:var(--portal-surface, #1c1c1c)}.resource-name{display:flex;align-items:center;gap:12px;border:0;background:none;text-align:left;padding:0;font-size:12px!important;max-width:400px}.resource-name>.iconify{font-size:17px;color:var(--portal-muted, #929292);flex-shrink:0}.resource-name span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.resource-name sma